"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'Dead End Street', 'author': 'Signature original', 'genre': 'Crime Noir', 'chapters': [{'n': 1, 'title': 'The Client', 'text': "That night Hank Mercer stood at the office window, watching the neon bleed into the wet street. a bloodstained matchbook sat in the safe. Outside, Grand Central Station did what it always did: it waited.\n\n'I need you to find out what this means,' the client said, laying a bloodstained matchbook on the desk like a bet. Hank Mercer had seen a hundred such objects. They all meant the same thing: somebody was lying, and somebody was going to bleed.\n\nLou the bartender whistled when they heard. 'the Club Owner is mixed up in this,' Lou the bartender said. 'You know what happened to the last shamus who crossed the Club Owner.' Hank Mercer knew. Everyone knew."}, {'n': 2, 'title': 'The Streets Talk', 'text': "Back at the office, Hank Mercer spread the pieces out: a bloodstained matchbook, the ledger page, Ruby's note. The shape of it was the Club Owner, big as a building. And Hank Mercer was just one detective with a gun and a grudge against lies.\n\nHank Mercer started where every case starts: the bars. Lou poured whiskey and talked about the Club Owner's new operation, about money moving through Grand Central Station like blood through a bad heart.\n\nThe address led to Grand Central Station's underbelly — a locker, a ledger, a man who didn't want to talk until Hank Mercer showed him a bloodstained matchbook. Then he talked like a river, and Hank Mercer wrote it all down."}, {'n': 3, 'title': "The Dame's Story", 'text': "She came back at midnight — the client, or the woman behind the client. Her story changed the way stories do when the truth puts on its coat. a bloodstained matchbook, she admitted, was stolen. From the Club Owner.\n\nThey tailed the Club Owner's fixer to a warehouse on the waterfront. What they saw there turned Hank Mercer's stomach: not just money, but the machinery of Grand Central Station's misery, oiled and humming.\n\nLou the bartender didn't like it. 'Dames,' Lou the bartender said, 'are how detectives get killed.' Hank Mercer agreed and kept the case anyway. Some habits are stronger than sense."}, {'n': 4, 'title': 'The Squeeze', 'text': "Ruby's club was next — a fire in the kitchen, a message in the smoke. Hank Mercer found her unharmed and furious, and that fury was worth ten guns. 'End this,' she said. Hank Mercer intended to.\n\nLou the bartender showed up bloody and grinning. 'They hit like accountants,' Lou the bartender said. Hank Mercer felt the cold anger settle in, the kind that doesn't shout, just aims.\n\nthe Club Owner squeezed back. First the office: tossed, the safe cracked, a bloodstained matchbook's copy gone — but Hank Mercer keeps the originals where no one looks. Then Lou the bartender: a warning delivered with fists in an alley off Grand Central Station."}, {'n': 5, 'title': 'The Confrontation', 'text': "It went down the way it always goes: shouting, threats, a gun that Hank Mercer was faster than. When the police took the Club Owner out, Grand Central Station seemed to exhale, like a drunk finally telling the truth.\n\n'You're finished,' Hank Mercer said. the Club Owner smiled the smile of someone who has bought judges. 'Am I?' Then Lou the bartender opened the door with the district attorney, and Ruby, and the dame's brother, alive, and the smile died.\n\nThe dame got her brother back and Hank Mercer got the rest of the fee, which was more than the insulting original. She cried. Hank Mercer didn't buy the tears but didn't charge for the shoulder, either."}, {'n': 6, 'title': 'Last Call', 'text': "Lou poured a double on the house. Ruby sang the song she only sings when she means it. Lou the bartender's ribs were taped, but Lou the bartender drank anyway, doctor's orders being for other people.\n\nThe phone rang. Hank Mercer picked it up. 'Hank Mercer Investigations,' Hank Mercer said, and listened, and smiled the thin smile of someone who knows exactly how much trouble costs. 'loyalty in a dirty town. I'll take the case.'\n\na bloodstained matchbook went into the office safe, next to the other honest things. Someday, Hank Mercer knew, someone would walk in with something like it, and it would start again. It always starts again."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

